using ClinicManager.DTO;using Microsoft.Data.SqlClient;using System.Data;
namespace ClinicManager.DAL;
public sealed class ClinicRepository
{
 const string Cs=@"Server=localhost\SQLEXPRESS;Database=ClinicDB;Trusted_Connection=True;TrustServerCertificate=True;";static SqlConnection Open(){var c=new SqlConnection(Cs);c.Open();return c;}
 public DataTable FindPatient(string phone){using var c=Open();using var x=new SqlCommand("SELECT MaBN,HoTen,SoDienThoai,NamSinh FROM dbo.BenhNhan WHERE SoDienThoai=@p",c);x.Parameters.Add("@p",SqlDbType.VarChar,15).Value=phone;using var a=new SqlDataAdapter(x);var t=new DataTable();a.Fill(t);return t;}
 public int RegisterPatient(string name,string phone,int? birth,string symptoms){using var c=Open();using var tx=c.BeginTransaction();try{int id;using(var x=new SqlCommand("INSERT dbo.BenhNhan(HoTen,SoDienThoai,NamSinh) VALUES(@n,@p,@y);SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){x.Parameters.Add("@n",SqlDbType.NVarChar,100).Value=name;x.Parameters.Add("@p",SqlDbType.VarChar,15).Value=phone;x.Parameters.Add("@y",SqlDbType.Int).Value=(object?)birth??DBNull.Value;id=Convert.ToInt32(x.ExecuteScalar());}int visit=CreateVisit(c,tx,id,symptoms);tx.Commit();return visit;}catch{tx.Rollback();throw;}}
 public int CreateVisit(int patientId,string symptoms){using var c=Open();using var tx=c.BeginTransaction();try{int id=CreateVisit(c,tx,patientId,symptoms);tx.Commit();return id;}catch{tx.Rollback();throw;}}
 static int CreateVisit(SqlConnection c,SqlTransaction tx,int patientId,string symptoms){using var x=new SqlCommand("INSERT dbo.HoSoKham(MaBN,TrieuChung) VALUES(@p,@s);SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx);x.Parameters.Add("@p",SqlDbType.Int).Value=patientId;x.Parameters.Add("@s",SqlDbType.NVarChar,-1).Value=symptoms;return Convert.ToInt32(x.ExecuteScalar());}
 public DataTable Medicines()=>Fill("SELECT MaThuoc,TenThuoc,DonViTinh,DonGia,SoLuongTon FROM dbo.Thuoc ORDER BY TenThuoc");
 public DataTable Visits()=>Fill("SELECT TOP 100 h.MaHoSo,b.HoTen,b.SoDienThoai,h.NgayKham,h.TrieuChung,h.ChanDoan FROM dbo.HoSoKham h JOIN dbo.BenhNhan b ON b.MaBN=h.MaBN ORDER BY h.MaHoSo DESC");
 DataTable Fill(string sql){using var c=Open();using var a=new SqlDataAdapter(sql,c);var t=new DataTable();a.Fill(t);return t;}
 public void SaveMedicine(int? id,string name,string unit,decimal price,int stock){using var c=Open();using var x=new SqlCommand(id==null?"INSERT dbo.Thuoc(TenThuoc,DonViTinh,DonGia,SoLuongTon) VALUES(@n,@u,@p,@s)":"UPDATE dbo.Thuoc SET TenThuoc=@n,DonViTinh=@u,DonGia=@p,SoLuongTon=@s WHERE MaThuoc=@id",c);x.Parameters.Add("@n",SqlDbType.NVarChar,150).Value=name;x.Parameters.Add("@u",SqlDbType.NVarChar,20).Value=unit;x.Parameters.Add("@p",SqlDbType.Decimal).Value=price;x.Parameters["@p"].Precision=18;x.Parameters["@p"].Scale=2;x.Parameters.Add("@s",SqlDbType.Int).Value=stock;if(id!=null)x.Parameters.Add("@id",SqlDbType.Int).Value=id;x.ExecuteNonQuery();}
 public int SavePrescription(int visitId,decimal consultationFee,string diagnosis,IReadOnlyList<PrescriptionLineDto> lines){if(lines.Count==0)throw new InvalidOperationException("Thêm ít nhất một loại thuốc vào đơn.");using var c=Open();using var tx=c.BeginTransaction();try{if(!string.IsNullOrWhiteSpace(diagnosis)){using var updateVisit=new SqlCommand("UPDATE dbo.HoSoKham SET ChanDoan=@diagnosis WHERE MaHoSo=@visit",c,tx);updateVisit.Parameters.Add("@diagnosis",SqlDbType.NVarChar,250).Value=diagnosis.Trim();updateVisit.Parameters.Add("@visit",SqlDbType.Int).Value=visitId;if(updateVisit.ExecuteNonQuery()!=1)throw new InvalidOperationException("Không tìm thấy hồ sơ khám.");}decimal total=consultationFee;foreach(var line in lines){using var price=new SqlCommand("SELECT DonGia FROM dbo.Thuoc WHERE MaThuoc=@id AND SoLuongTon>=@qty",c,tx);price.Parameters.Add("@id",SqlDbType.Int).Value=line.MedicineId;price.Parameters.Add("@qty",SqlDbType.Int).Value=line.Quantity;var result=price.ExecuteScalar();if(result==null)throw new InvalidOperationException($"Thuốc {line.Medicine} không đủ tồn kho.");total+=Convert.ToDecimal(result)*line.Quantity;}int id;using(var order=new SqlCommand("INSERT dbo.DonThuoc(MaHoSo,TienKham,TongTien,TrangThai) VALUES(@v,@fee,@total,N'Chờ thanh toán');SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){order.Parameters.Add("@v",SqlDbType.Int).Value=visitId;var f=order.Parameters.Add("@fee",SqlDbType.Decimal);f.Precision=18;f.Scale=2;f.Value=consultationFee;var t=order.Parameters.Add("@total",SqlDbType.Decimal);t.Precision=18;t.Scale=2;t.Value=total;id=Convert.ToInt32(order.ExecuteScalar());}foreach(var line in lines){using var detail=new SqlCommand("INSERT dbo.ChiTietDonThuoc(MaDon,MaThuoc,SoLuong,LieuDung) VALUES(@o,@m,@q,@u);UPDATE dbo.Thuoc SET SoLuongTon=SoLuongTon-@q WHERE MaThuoc=@m AND SoLuongTon>=@q",c,tx);detail.Parameters.Add("@o",SqlDbType.Int).Value=id;detail.Parameters.Add("@m",SqlDbType.Int).Value=line.MedicineId;detail.Parameters.Add("@q",SqlDbType.Int).Value=line.Quantity;detail.Parameters.Add("@u",SqlDbType.NVarChar,100).Value=line.Usage;if(detail.ExecuteNonQuery()!=2)throw new InvalidOperationException($"Tồn kho thuốc {line.Medicine} vừa thay đổi, đơn đã hủy.");}tx.Commit();return id;}catch{tx.Rollback();throw;}}
 public void Pay(int orderId){using var c=Open();using var x=new SqlCommand("UPDATE dbo.DonThuoc SET TrangThai=N'Đã thanh toán' WHERE MaDon=@id AND TrangThai<>N'Đã thanh toán'",c);x.Parameters.Add("@id",SqlDbType.Int).Value=orderId;if(x.ExecuteNonQuery()!=1)throw new InvalidOperationException("Không tìm thấy đơn chờ thanh toán.");}
 public DataTable Invoice(int id){using var c=Open();using var x=new SqlCommand("SELECT d.MaDon,d.TrangThai,d.TienKham,d.TongTien,t.TenThuoc,c.SoLuong,c.LieuDung,t.DonGia*c.SoLuong AS ThanhTien FROM dbo.DonThuoc d JOIN dbo.ChiTietDonThuoc c ON c.MaDon=d.MaDon JOIN dbo.Thuoc t ON t.MaThuoc=c.MaThuoc WHERE d.MaDon=@id",c);x.Parameters.Add("@id",SqlDbType.Int).Value=id;using var a=new SqlDataAdapter(x);var t=new DataTable();a.Fill(t);return t;}
}
